#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, T;
    cin >> N >> T;

    vector<int> type(N), price(N);
    for (int &x : type) cin >> x;
    for (int &x : price) cin >> x;

    vector<priority_queue<int, vector<int>, greater<int>>> stock(T + 1);
    for (int i = 0; i < N; ++i) {
        stock[type[i]].push(price[i]);
    }

    using Entry = tuple<int, int, int>; // price, type, version
    priority_queue<Entry, vector<Entry>, greater<Entry>> global;
    vector<int> version(T + 1, 0);

    for (int t = 1; t <= T; ++t) {
        if (!stock[t].empty()) {
            global.emplace(stock[t].top(), t, version[t]);
        }
    }

    auto removeItem = [&](int t) {
        stock[t].pop();
        ++version[t];
        if (!stock[t].empty()) {
            global.emplace(stock[t].top(), t, version[t]);
        }
    };

    int C;
    cin >> C;

    long long total = 0;
    for (int i = 0; i < C; ++i) {
        int u;
        cin >> u;

        if (u != 0) {
            if (!stock[u].empty()) {
                total += stock[u].top();
                removeItem(u);
            }
        } else {
            while (!global.empty()) {
                auto [p, t, v] = global.top();
                if (v != version[t] || stock[t].empty()) {
                    global.pop();
                } else {
                    break;
                }
            }

            if (!global.empty()) {
                auto [p, t, v] = global.top();
                global.pop();
                total += p;
                removeItem(t);
            }
        }
    }

    cout << total << '\n';
    return 0;
}
